/**
 * Types for the generated resource registry (src/registry/). The registry itself is generated by
 * scripts/gen-registry.ts and must not be hand-edited.
 */
import type { Toolset } from "./config.js";

export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

/**
 * Standard kinds map onto the generic tools. `view` ops are extra reads reached through the
 * `view` param of list/get; `action` ops are extra writes reached through wxcc-ext-action.
 */
export type OpKind =
  | "list"
  | "get"
  | "create"
  | "update"
  | "patch"
  | "delete"
  | "bulkSave"
  | "bulkPatch"
  | "references"
  | "view"
  | "action";

export interface QueryParam {
  name: string;
  type: "string" | "integer" | "boolean" | "string[]";
  required: boolean;
  default?: string;
  enum?: string[];
}

export interface RegistryOperation {
  kind: OpKind;
  /** Set for view/action ops, e.g. "reassign-agents", "purge-inactive". */
  name?: string;
  method: HttpMethod;
  /** Path template, e.g. "/organization/{orgid}/v2/team/{id}" or "/{orgid}/project/<id>/flows". */
  path: string;
  apiVersion: number;
  /** Placeholders other than {orgid}. */
  pathParams: string[];
  queryParams: QueryParam[];
  /** Query values sent when the caller gives none: safer than the API's own defaults. */
  sendDefaults?: Record<string, string>;
  hasBody: boolean;
  bodyEncoding?: "json" | "multipart";
  /** For multipart bodies: the binary part and the JSON part carrying the record's fields. */
  multipartParts?: { file: string; json: string };
  paginated: boolean;
  summary: string;
  /** Key of the source operation ("METHOD path") in apireference/openapi/*.json. */
  source: string;
}

export type UpdateSemantics = "put-full-replace" | "patch-partial" | "put-and-patch" | "none";

export interface RegistryEntry {
  key: string;
  displayName: string;
  description: string;
  aliases: string[];
  toolset: Toolset;
  singleton: boolean;
  idField: "id";
  parent?: { resource: string; param: string };
  updateSemantics: UpdateSemantics;
  /** Stripped from a merged PUT body. */
  readOnlyFields: string[];
  requiredOnCreate: string[];
  operations: RegistryOperation[];
}

/** Full schemas for one resource, loaded lazily by describe_resource. */
export interface ResourceSchemaDoc {
  key: string;
  operations: Record<
    string,
    {
      method: HttpMethod;
      path: string;
      summary: string;
      description?: string;
      queryParams: Array<QueryParam & { description?: string }>;
      requestBody?: unknown;
      response?: unknown;
    }
  >;
}
